def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3

    try:
        value = (v1 + v2 + v3) / count
    except ZeroDivisionError:
        return None

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
